node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Search for the LogiTech Wireless Mouse M310
const products = db.prepare(\"SELECT * FROM products WHERE name LIKE '%M310%' OR name LIKE '%LogiTech%Wireless%Mouse%'\").all();
console.log('=== Matching Products ===');
for (const p of products) {
  console.log(JSON.stringify(p, null, 2));
}

// Also check rt_variants for these products
if (products.length > 0) {
  for (const p of products) {
    const variants = db.prepare('SELECT * FROM rt_variants WHERE product_id = ?').all(p.product_id);
    if (variants.length > 0) {
      console.log('\n=== Variants for ' + p.product_id + ' ===');
      for (const v of variants) {
        console.log(JSON.stringify(v, null, 2));
      }
    }
  }
}
"

